param([ValidateSet('x86', 'x64')][string]$CompileArchitecture,
  [string]$SourceDirectory = (Join-Path (Split-Path $PSScriptRoot -Parent) '.deps/dxvk-remix'),
  [string]$OutputDirectory = (Join-Path (Split-Path $PSScriptRoot -Parent) '.deps/steam-window-test'))
$ErrorActionPreference = 'Stop'
$repoRoot = Split-Path $PSScriptRoot -Parent
. (Join-Path $PSScriptRoot 'assert_native_architecture.ps1')
$source = (Resolve-Path -LiteralPath $SourceDirectory).Path
New-Item -ItemType Directory -Force $OutputDirectory | Out-Null
$testDir = (Resolve-Path -LiteralPath $OutputDirectory).Path
if ($CompileArchitecture) {
  . (Join-Path $PSScriptRoot 'setup_native_test_compiler.ps1')
  Set-NativeTestCompiler -Architecture $CompileArchitecture
  Push-Location $testDir
  try {
    & cl.exe /nologo /std:c++17 /EHsc /W4 /WX /LD "$repoRoot/tests/steam_window_fixture.cpp" "/Fe:window-fixture-$CompileArchitecture.dll" /link user32.lib "/DEF:$repoRoot/tests/steam_window_fixture.def"
    if ($LASTEXITCODE -ne 0) { throw 'Window fixture compilation failed' }
    & cl.exe /nologo /std:c++17 /EHsc /W4 /WX "/I$source/bridge/src/server" "$repoRoot/tests/steam_window_diagnostics.cpp" user32.lib "/Fe:window-test-$CompileArchitecture.exe"
    if ($LASTEXITCODE -ne 0) { throw 'Window diagnostic compilation failed' }
    & cl.exe /nologo /std:c++17 /EHsc /W4 /WX "/I$source/bridge/src/server" "$repoRoot/tests/steam_window_adapter.cpp" user32.lib "/Fe:adapter-test-$CompileArchitecture.exe"
    if ($LASTEXITCODE -ne 0) { throw 'Window adapter compilation failed' }
    $control = Join-Path $testDir "unpinned-headers-$CompileArchitecture"
    & python "$PSScriptRoot/generate_steam_native_controls.py" --source $source --output $control --mode observer-unpinned
    if ($LASTEXITCODE -ne 0) { throw 'Exact observer PIN negative-control generation failed' }
    foreach ($variant in @('production', 'unpinned')) {
      $include = if ($variant -eq 'production') { "$source/bridge/src/server" } else { $control }
      & cl.exe /nologo /std:c++17 /EHsc /O2 /MT /W4 /WX /LD "/I$include" "$repoRoot/tests/steam_window_lifetime_observer.cpp" "/Fe:observer-$variant-$CompileArchitecture.dll" /link user32.lib "/DEF:$repoRoot/tests/steam_window_lifetime_observer.def"
      if ($LASTEXITCODE -ne 0) { throw "Window observer DLL compilation failed: $variant" }
      Assert-NativeArchitecture -Path (Join-Path $testDir "observer-$variant-$CompileArchitecture.dll") -Architecture $CompileArchitecture
    }
    & cl.exe /nologo /std:c++17 /EHsc /O2 /MT /W4 /WX "$repoRoot/tests/steam_window_lifetime.cpp" user32.lib "/Fe:lifetime-test-$CompileArchitecture.exe"
    if ($LASTEXITCODE -ne 0) { throw 'Window observer lifecycle fixture compilation failed' }
    Assert-NativeArchitecture -Path (Join-Path $testDir "lifetime-test-$CompileArchitecture.exe") -Architecture $CompileArchitecture
    Assert-NativeArchitecture -Path (Join-Path $testDir "adapter-test-$CompileArchitecture.exe") -Architecture $CompileArchitecture
    Assert-NativeArchitecture -Path (Join-Path $testDir "window-fixture-$CompileArchitecture.dll") -Architecture $CompileArchitecture
    Assert-NativeArchitecture -Path (Join-Path $testDir "window-test-$CompileArchitecture.exe") -Architecture $CompileArchitecture
  } finally { Pop-Location }
} else {
  foreach ($arch in @('x86', 'x64')) {
    & powershell.exe -NoProfile -ExecutionPolicy Bypass -File $PSCommandPath -CompileArchitecture $arch -SourceDirectory $SourceDirectory -OutputDirectory $testDir
    if ($LASTEXITCODE -ne 0) { throw "Window diagnostic compilation failed for $arch" }
  }
  $lifetimeResults = @()
  foreach ($arch in @('x86', 'x64')) {
    $other = if ($arch -eq 'x86') { 'x64' } else { 'x86' }
    & (Join-Path $testDir "adapter-test-$arch.exe") (Join-Path $testDir "window-fixture-$arch.dll") (Join-Path $testDir "adapter-test-$other.exe")
    if ($LASTEXITCODE -ne 0) { throw "Cross-architecture window adapter failed for $arch" }
    foreach ($mode in @('real', 'chain')) {
      & (Join-Path $testDir "window-test-$arch.exe") (Join-Path $testDir "window-fixture-$arch.dll") $mode
      if ($LASTEXITCODE -ne 0) { throw "Window diagnostic failed for $arch / $mode" }
    }
    foreach ($variant in @('production', 'unpinned')) {
      $process = [System.Diagnostics.Process]::new()
      $process.StartInfo.FileName = Join-Path $testDir "lifetime-test-$arch.exe"
      $renderer = Join-Path $testDir "window-fixture-$arch.dll"
      $observer = Join-Path $testDir "observer-$variant-$arch.dll"
      $process.StartInfo.Arguments = '"' + $renderer + '" "' + $observer + '"'
      $process.StartInfo.UseShellExecute = $false
      $process.StartInfo.CreateNoWindow = $true
      $process.StartInfo.RedirectStandardOutput = $true
      $process.StartInfo.RedirectStandardError = $true
      try {
        if (!$process.Start()) { throw 'Cannot start observer lifecycle fixture' }
        $output = $process.StandardOutput.ReadToEnd() + $process.StandardError.ReadToEnd()
        $process.WaitForExit()
        $code = $process.ExitCode
      } finally { $process.Dispose() }
      $output | Set-Content -LiteralPath (Join-Path $testDir "lifetime-$variant-$arch.txt") -Encoding utf8
      Write-Host $output
      $expected = if ($variant -eq 'production') { 0 } else { 42 }
      if ($code -ne $expected -or ($variant -eq 'unpinned' -and $output -notmatch 'FAIL observer lifecycle: observer unloaded after stop/FreeLibrary; retained callback not invoked')) {
        throw "Observer lifecycle regression did not produce its exact expected result: $arch/$variant exit=$code"
      }
      $lifetimeResults += @{ variant=$variant; architecture=$arch; exit_code=$code; expected_exit_code=$expected; passed=$true }
    }
  }
  @{ source=$source; source_header_sha256=(Get-FileHash "$source/bridge/src/server/steam_window_diagnostics.h" -Algorithm SHA256).Hash.ToLower(); tests=$lifetimeResults } |
    ConvertTo-Json -Depth 5 | Set-Content -LiteralPath (Join-Path $testDir 'lifetime-results.json') -Encoding utf8
}
